/* River meander simulation, run in a WorkerScript thread so plasmashell's UI never waits for it.
 *
 * The river is a polyline (the channel centreline) flowing left to right. Each step every point moves sideways at a
 * rate set by the channel curvature at that point and, weighted by an exponential, the curvature upstream of it
 * (Howard & Knutson 1984, the model behind Sylvester's "meanderpy"). That lag is what makes bends grow, lean
 * downstream and tighten. When two reaches of the channel touch, the loop between them is cut off and returned as an
 * oxbow lake. All lengths are logical pixels.
 *
 * A river needs tens of thousands of steps to mature, too long to wait for at login, so a mature one is baked in at
 * the bottom of this file (BAKED, in channel widths; made by tools/bake.js). A new river is a randomly chosen
 * stretch of it, aged a little further to give it a past.
 *
 * Messages in:  { cmd: "init", w, h, cw, seed, warm, history, every, era, dt }   start a river and age it
 *               { cmd: "step", n }                                           advance n steps
 * Messages out: { kind: "init", pts, eras: [[polyline, ...] oldest era first], era }
 *               { kind: "step", pts, oxbows: [polyline, ...], step }
 * A polyline is a flat array [x0, y0, x1, y1, ...].
 */
var S = null

function mulberry(a) {
    return function () {
        a |= 0; a = a + 0x6D2B79F5 | 0
        var t = Math.imul(a ^ a >>> 15, 1 | a)
        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t
        return ((t ^ t >>> 14) >>> 0) / 4294967296
    }
}

function init(p) {
    var cw = p.cw, ds = cw * 0.6, margin = Math.max(500, p.w * 0.2)
    var n = Math.ceil((p.w + 2 * margin) / ds) + 1
    var rnd = mulberry(p.seed || 1)
    var x = new Array(n), y = new Array(n), yc = p.h * 0.5
    var a1 = rnd() * 6.28, a2 = rnd() * 6.28, a3 = rnd() * 6.28
    for (var i = 0; i < n; i++) {
        x[i] = -margin + i * ds
        y[i] = yc + cw * (0.6 * Math.sin(x[i] / (cw * 9) + a1) + 0.4 * Math.sin(x[i] / (cw * 5.3) + a2)
                          + 0.3 * Math.sin(x[i] / (cw * 16) + a3)) + (rnd() - 0.5) * cw * 0.2
    }
    if (typeof BAKED !== "undefined" && !p.fresh) {
        // a random stretch of the baked river, long enough to cover the screen and both margins
        var nb = BAKED.length / 2, len = (p.w + 2 * margin) / cw, x0 = BAKED[0], x1 = BAKED[2 * nb - 2]
        var start = x0 + rnd() * Math.max(0, x1 - x0 - len), i0 = 0, i1 = nb - 1, my = 0
        while (i0 < nb - 1 && BAKED[2 * i0] < start) i0++
        while (i1 > i0 + 2 && BAKED[2 * i1] > start + len) i1--
        x = []; y = []
        for (i = i0; i <= i1; i++) my += BAKED[2 * i + 1]
        my /= (i1 - i0 + 1)
        var flip = rnd() < 0.5 ? -1 : 1
        for (i = i0; i <= i1; i++) { x.push((BAKED[2 * i] - start) * cw - margin); y.push(yc + flip * (BAKED[2 * i + 1] - my) * cw) }
    }
    S = { w: p.w, h: p.h, cw: cw, ds: ds, margin: margin, yc: yc, x: x, y: y, rnd: rnd, step: 0, oxbows: [],
          wob: rnd() * 6.28, dt: p.dt || 1 }
}

function stepOnce() {
    var x = S.x, y = S.y, n = x.length, cw = S.cw, ds = S.ds, i, j
    var dt = S.dt, kl = 0.5 * dt, omega = -1.0, gamma = 2.5, alpha = 1 / (cw * 2.6), vmax = 0.3 * dt
    var K = Math.ceil(4 / (alpha * ds))
    // tangents and curvature
    var tx = new Array(n), ty = new Array(n), R0 = new Array(n)
    for (i = 0; i < n; i++) {
        var a = i > 0 ? i - 1 : 0, b = i < n - 1 ? i + 1 : n - 1
        var dx = x[b] - x[a], dy = y[b] - y[a], l = Math.sqrt(dx * dx + dy * dy) || 1
        tx[i] = dx / l; ty[i] = dy / l
    }
    for (i = 0; i < n; i++) {
        a = i > 0 ? i - 1 : 0; b = i < n - 1 ? i + 1 : n - 1
        var seg = Math.sqrt((x[b] - x[a]) * (x[b] - x[a]) + (y[b] - y[a]) * (y[b] - y[a])) || 1
        var curv = (tx[i] * (ty[b] - ty[a]) - ty[i] * (tx[b] - tx[a])) / seg
        R0[i] = kl * cw * curv
    }
    // migration rate: local curvature plus the exponentially weighted curvature upstream
    var G = new Array(K + 1), gs = 0
    for (j = 0; j <= K; j++) { G[j] = Math.exp(-alpha * j * ds); gs += G[j] }
    var band = S.h * 0.4, yc = S.yc
    var nx = new Array(n), ny = new Array(n)
    for (i = 0; i < n; i++) {
        var acc = 0
        for (j = 0; j <= K; j++) acc += R0[i - j < 0 ? 0 : i - j] * G[j]
        var r = omega * R0[i] + gamma * acc / gs
        if (r > vmax) r = vmax; else if (r < -vmax) r = -vmax
        nx[i] = x[i] + r * ty[i]
        ny[i] = y[i] - r * tx[i]
        // the valley walls: outside the band the channel is eased back
        var over = ny[i] - yc
        ny[i] -= over * 0.00012 * dt
        if (over > band) ny[i] -= (over - band) * 0.006 * dt
        else if (over < -band) ny[i] -= (over + band) * 0.006 * dt
    }
    // the inflow wobbles slowly so new bends keep being born upstream; both ends stay on the valley axis
    S.wob += 0.0021 * dt
    var pin = 12
    for (i = 0; i < pin; i++) {
        var f = i / pin
        nx[i] = -S.margin + i * ds
        ny[i] = ny[i] * f + (yc + cw * 1.5 * Math.sin(S.wob) * f) * (1 - f)
        var e = n - 1 - i
        nx[e] = S.w + S.margin - i * ds
        ny[e] = ny[e] * f + yc * (1 - f)
    }
    // light smoothing, then resample to even spacing
    var sx = new Array(n), sy = new Array(n), sm = 0.12
    sx[0] = nx[0]; sy[0] = ny[0]; sx[n - 1] = nx[n - 1]; sy[n - 1] = ny[n - 1]
    for (i = 1; i < n - 1; i++) {
        sx[i] = nx[i] + sm * ((nx[i - 1] + nx[i + 1]) * 0.5 - nx[i])
        sy[i] = ny[i] + sm * ((ny[i - 1] + ny[i + 1]) * 0.5 - ny[i])
    }
    var rx = [sx[0]], ry = [sy[0]], need = ds
    for (i = 1; i < n; i++) {
        var px = sx[i - 1], py = sy[i - 1], qx = sx[i], qy = sy[i]
        var sl = Math.sqrt((qx - px) * (qx - px) + (qy - py) * (qy - py))
        while (sl >= need) {
            var t = need / sl
            px += (qx - px) * t; py += (qy - py) * t
            rx.push(px); ry.push(py)
            sl -= need; need = ds
        }
        need -= sl
    }
    rx.push(sx[n - 1]); ry.push(sy[n - 1])
    S.x = rx; S.y = ry
    S.step++
    if (S.step % 4 === 0) cutoffs()
}

// where two reaches come within a channel width of each other, drop the loop between them
function cutoffs() {
    var x = S.x, y = S.y, n = x.length, cr = S.cw * 1.15, gap = Math.ceil(S.cw * 6 / S.ds)
    for (var guard = 0; guard < 8; guard++) {
        var grid = {}, hit = null, i
        for (i = 0; i < n && !hit; i++) {
            var gx = Math.floor(x[i] / cr), gy = Math.floor(y[i] / cr)
            for (var ox = -1; ox <= 1 && !hit; ox++) for (var oy = -1; oy <= 1 && !hit; oy++) {
                var cell = grid[(gx + ox) + "," + (gy + oy)]
                if (!cell) continue
                for (var k = 0; k < cell.length; k++) {
                    var j = cell[k]
                    if (i - j > gap && (x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]) < cr * cr) { hit = [j, i]; break }
                }
            }
            var key = gx + "," + gy
            if (grid[key]) grid[key].push(i); else grid[key] = [i]
        }
        if (!hit) break
        var loop = []
        for (i = hit[0]; i <= hit[1]; i++) loop.push(x[i], y[i])
        loop.push(x[hit[0]], y[hit[0]])
        S.oxbows.push(loop)
        x.splice(hit[0] + 1, hit[1] - hit[0] - 1); y.splice(hit[0] + 1, hit[1] - hit[0] - 1)
        n = x.length
    }
}

function flat() {
    var x = S.x, y = S.y, n = x.length, out = new Array(n * 2)
    for (var i = 0; i < n; i++) { out[2 * i] = Math.round(x[i] * 10) / 10; out[2 * i + 1] = Math.round(y[i] * 10) / 10 }
    return out
}

function handle(m) {
    if (m.cmd === "init") {
        init(m)
        var i
        for (i = 0; i < m.warm; i++) stepOnce()
        // the last `history` steps are kept as snapshots, grouped into eras, so the wallpaper can open with a past
        var eras = [], cur = []
        for (i = 0; i < m.history; i++) {
            stepOnce()
            if (i % m.every === 0) cur.push(flat())
            if ((i + 1) % m.era === 0) { eras.push(cur); cur = [] }
        }
        if (cur.length) eras.push(cur)
        S.oxbows = []
        S.dt = 1
        return { kind: "init", pts: flat(), eras: eras, step: S.step }
    }
    if (m.cmd === "step" && S) {
        for (var k = 0; k < (m.n || 1); k++) stepOnce()
        var ox = S.oxbows
        S.oxbows = []
        return { kind: "step", pts: flat(), oxbows: ox, step: S.step }
    }
    return null
}

if (typeof WorkerScript !== "undefined") {
    WorkerScript.onMessage = function (m) {
        var r = handle(m)
        if (r) WorkerScript.sendMessage(r)
    }
}

